/**
 * The CodeMirror 6 editor (spec features 4, 12 and 13).
 *
 * Undo/redo comes from CodeMirror's own history, and inline diagnostics are
 * pushed in from the render pipeline rather than computed by a second parser
 * inside the editor.
 */

import {
  acceptCompletion,
  autocompletion,
  closeBrackets,
  closeBracketsKeymap,
} from '@codemirror/autocomplete';
import {
  defaultKeymap,
  history,
  historyKeymap,
  indentWithTab,
  redo,
  undo,
} from '@codemirror/commands';
import { bracketMatching, foldGutter, foldKeymap, indentOnInput, indentUnit } from '@codemirror/language';
import { Diagnostic as CmDiagnostic, lintGutter, setDiagnostics } from '@codemirror/lint';
import { highlightSelectionMatches, searchKeymap } from '@codemirror/search';
import { Compartment, EditorState, Extension, Prec } from '@codemirror/state';
import {
  EditorView,
  drawSelection,
  dropCursor,
  highlightActiveLine,
  highlightActiveLineGutter,
  highlightSpecialChars,
  keymap,
  lineNumbers,
  rectangularSelection,
} from '@codemirror/view';

import type { Diagnostic } from '@betterscad/engine';
import { openscad } from './scad-language.js';
import { scadCompletions } from './completions.js';
import { inchEntry } from './units.js';
import { parameterCompletions, signatureHelp } from './signature.js';

/**
 * Tab, when there is a suggestion open.
 *
 * `Prec.high` rather than a position in the extension list: `indentWithTab`
 * sits in the main keymap at ordinary precedence, and this has to be offered
 * the key first. It is not a replacement for it — `acceptCompletion` declines
 * when no completion is open, and the key falls through to indenting, which is
 * what makes one binding serve both habits.
 */
function tabCompletionKeymap(on: boolean): Extension {
  return on ? Prec.high(keymap.of([{ key: 'Tab', run: acceptCompletion }])) : [];
}

/** The settings the editor itself acts on. */
export interface EditorSettings {
  /** Rewrite `5in` to millimetres as it is typed. */
  inchEntry: boolean;
  /** Spaces per indent. */
  indentWidth: number;
  /** Tab takes the open suggestion, rather than always indenting. */
  tabCompletion: boolean;
}

export interface EditorCallbacks {
  onChange(source: string): void;
  onCursor(line: number, column: number): void;
  /** F5 / F6 and the other render shortcuts are owned by the app, not the editor. */
  onShortcut(name: string): boolean;
}

/**
 * Theme.
 *
 * Everything resolves to brand tokens, so switching light/dark needs no
 * editor reconfiguration — the CSS variables change underneath it.
 */
const theme = EditorView.theme({
  '&': {
    height: '100%',
    backgroundColor: 'var(--bs-surface)',
    color: 'var(--bs-text)',
  },
  '.cm-content': { caretColor: 'var(--bs-solid-500)' },
  '.cm-cursor, .cm-dropCursor': { borderLeftColor: 'var(--bs-solid-500)', borderLeftWidth: '2px' },
  /*
   * Spelled out to the full depth the base theme uses, because the base theme
   * wins otherwise. CodeMirror styles the focused selection at
   * `&light.cm-focused > .cm-scroller > .cm-selectionLayer .cm-selectionBackground`
   * — five classes — and the usual short form here is four, so an opaque
   * `#d7d4f0` was painting over the code and taking the syntax colours with it.
   * Matching the path outranks it, and does so in either mode rather than
   * relying on which of `cm-light` / `cm-dark` the editor is carrying.
   */
  '&.cm-focused > .cm-scroller > .cm-selectionLayer .cm-selectionBackground': {
    backgroundColor: 'color-mix(in srgb, var(--bs-solid-500) 28%, transparent)',
  },
  '& > .cm-scroller > .cm-selectionLayer .cm-selectionBackground': {
    backgroundColor: 'color-mix(in srgb, var(--bs-solid-500) 18%, transparent)',
  },
  '& .cm-content ::selection': {
    backgroundColor: 'color-mix(in srgb, var(--bs-solid-500) 28%, transparent)',
  },
  '.cm-gutters': {
    backgroundColor: 'var(--bs-surface)',
    color: 'var(--bs-text-faint)',
    border: 'none',
    borderRight: '1px solid var(--bs-border)',
  },
  '.cm-activeLineGutter': { backgroundColor: 'var(--bs-surface-sunken)', color: 'var(--bs-text-muted)' },
  '.cm-activeLine': { backgroundColor: 'color-mix(in srgb, var(--bs-text) 4%, transparent)' },
  '.cm-selectionMatch': { backgroundColor: 'color-mix(in srgb, var(--bs-cut-300) 22%, transparent)' },
  '.cm-matchingBracket, &.cm-focused .cm-matchingBracket': {
    backgroundColor: 'color-mix(in srgb, var(--bs-cut-300) 30%, transparent)',
    outline: 'none',
  },
  '.cm-tooltip': {
    backgroundColor: 'var(--bs-surface-raised)',
    border: '1px solid var(--bs-border)',
    borderRadius: 'var(--bs-radius)',
    boxShadow: 'var(--bs-shadow-2)',
  },
  '.cm-tooltip-autocomplete > ul > li[aria-selected]': {
    backgroundColor: 'var(--bs-solid-500)',
    color: '#fff',
  },
  // Several call forms share a name — `cylinder` appears once per way of
  // writing it — so the argument list beside it is what the reader picks from.
  // Italic at body weight is not enough to scan a column of them by; this makes
  // it read as the code it is.
  '.cm-completionDetail': {
    fontStyle: 'normal',
    fontFamily: 'var(--bs-font-mono)',
    fontSize: '0.92em',
    opacity: '0.75',
  },
  '.cm-tooltip-autocomplete > ul > li[aria-selected] .cm-completionDetail': { opacity: '0.85' },
  '.cm-completionInfo': {
    maxWidth: '340px',
    padding: '8px 10px',
    backgroundColor: 'var(--bs-surface-raised)',
    border: '1px solid var(--bs-border)',
    borderRadius: 'var(--bs-radius)',
    whiteSpace: 'pre-wrap',
  },
  '.cm-panels': { backgroundColor: 'var(--bs-surface-sunken)', color: 'var(--bs-text)' },
  '.cm-searchMatch': { backgroundColor: 'color-mix(in srgb, var(--bs-solid-500) 30%, transparent)' },
  '.cm-lintRange-error': { backgroundImage: 'none', borderBottom: '2px wavy var(--bs-danger)' },
  '.cm-lintRange-warning': { backgroundImage: 'none', borderBottom: '2px wavy var(--bs-warning)' },
});

export class ScadEditor {
  readonly view: EditorView;
  private readonly readOnly = new Compartment();
  // Two settings the user can change while the editor is open. Compartments
  // rather than a rebuilt state, so changing one keeps the undo history.
  private readonly inchEntry = new Compartment();
  private readonly indent = new Compartment();
  private readonly tabCompletion = new Compartment();
  /**
   * Which of `cm-light` / `cm-dark` the editor carries.
   *
   * The app's own colours are CSS variables and follow `data-theme` on their
   * own, but CodeMirror's base theme has hardcoded light and dark variants and
   * picks between them with this facet. Left at its default the editor claimed
   * to be light whatever the app was, and every base rule that differs between
   * the two — the selection being the one that showed — came out wrong.
   */
  private readonly darkMode = new Compartment();
  private readonly extensions: Extension[];
  /** Set while `setSource` is replacing the document, to suppress onChange. */
  private applyingExternalEdit = false;

  constructor(
    parent: HTMLElement,
    initialSource: string,
    private readonly callbacks: EditorCallbacks,
    settings: EditorSettings = { inchEntry: true, indentWidth: 2, tabCompletion: true },
    dark = true,
  ) {
    const shortcutKeymap = [
      { key: 'F5', run: () => this.shortcut('preview'), preventDefault: true },
      { key: 'F6', run: () => this.shortcut('render'), preventDefault: true },
      { key: 'Mod-s', run: () => this.shortcut('save'), preventDefault: true },
      { key: 'Mod-Shift-s', run: () => this.shortcut('save-as'), preventDefault: true },
      { key: 'Mod-o', run: () => this.shortcut('open'), preventDefault: true },
      { key: 'Mod-e', run: () => this.shortcut('export'), preventDefault: true },
      { key: 'Mod-Shift-p', run: () => this.shortcut('palette'), preventDefault: true },
      // ⌘K is what the toolbar's search field advertises, and what people
      // arriving from any other editor will reach for first.
      { key: 'Mod-k', run: () => this.shortcut('palette'), preventDefault: true },
      { key: 'Mod-Enter', run: () => this.shortcut('render'), preventDefault: true },
    ];

    const extensions: Extension[] = [
      this.darkMode.of(EditorView.darkTheme.of(dark)),
      lineNumbers(),
      highlightActiveLineGutter(),
      highlightSpecialChars(),
      history(),
      foldGutter(),
      drawSelection(),
      dropCursor(),
      EditorState.allowMultipleSelections.of(true),
      indentOnInput(),
      this.indent.of(indentUnit.of(' '.repeat(settings.indentWidth))),
      bracketMatching(),
      closeBrackets(),
      // Two sources, because they answer different questions: which parameters
      // this call still takes, and what the language has by that name.
      autocompletion({
        override: [parameterCompletions, scadCompletions],
        activateOnTyping: true,
        icons: true,
      }),
      // Keeps the signature on screen for as long as the cursor is between the
      // brackets, which is exactly when autocomplete has nothing more to say.
      signatureHelp(),
      rectangularSelection(),
      highlightActiveLine(),
      highlightSelectionMatches(),
      lintGutter(),
      // Shortcuts come first so F5 reaches the app instead of the browser.
      keymap.of([
        ...shortcutKeymap,
        ...closeBracketsKeymap,
        ...defaultKeymap,
        ...searchKeymap,
        ...historyKeymap,
        ...foldKeymap,
        indentWithTab,
      ]),
      openscad(),
      theme,
      EditorView.lineWrapping,
      this.readOnly.of(EditorState.readOnly.of(false)),
      this.inchEntry.of(settings.inchEntry ? inchEntry() : []),
      this.tabCompletion.of(tabCompletionKeymap(settings.tabCompletion)),
      EditorView.updateListener.of((update) => {
        if (update.docChanged && !this.applyingExternalEdit) {
          this.callbacks.onChange(update.state.doc.toString());
        }
        if (update.selectionSet || update.docChanged) {
          const head = update.state.selection.main.head;
          const line = update.state.doc.lineAt(head);
          this.callbacks.onCursor(line.number, head - line.from + 1);
        }
      }),
    ];

    this.extensions = extensions;
    this.view = new EditorView({
      parent,
      state: EditorState.create({ doc: initialSource, extensions }),
    });
  }

  /** Whether Tab takes the open suggestion before it falls back to indenting. */
  setTabCompletion(on: boolean): void {
    this.view.dispatch({ effects: this.tabCompletion.reconfigure(tabCompletionKeymap(on)) });
  }

  /** Follows the app's light/dark toggle; see `darkMode`. */
  setDark(dark: boolean): void {
    this.view.dispatch({ effects: this.darkMode.reconfigure(EditorView.darkTheme.of(dark)) });
  }

  /** Turns inch entry on or off without disturbing the document. */
  setInchEntry(on: boolean): void {
    this.view.dispatch({
      effects: this.inchEntry.reconfigure(on ? inchEntry() : []),
    });
  }

  setIndentWidth(width: number): void {
    this.view.dispatch({
      effects: this.indent.reconfigure(indentUnit.of(' '.repeat(width))),
    });
  }

  /** A fresh state for a document, with this editor's full extension set. */
  createState(source: string): EditorState {
    return EditorState.create({ doc: source, extensions: this.extensions });
  }

  private shortcut(name: string): boolean {
    return this.callbacks.onShortcut(name);
  }

  get source(): string {
    return this.view.state.doc.toString();
  }

  /**
   * Replaces the document's text in place, keeping undo history.
   *
   * Used when the same document's content changes underneath the editor —
   * reverting, or applying Customizer values back to the source.
   */
  setSource(source: string): void {
    if (source === this.source) return;
    this.applyingExternalEdit = true;
    try {
      const previousHead = this.view.state.selection.main.head;
      this.view.dispatch({
        changes: { from: 0, to: this.view.state.doc.length, insert: source },
        selection: { anchor: Math.min(previousHead, source.length) },
      });
    } finally {
      this.applyingExternalEdit = false;
    }
  }

  /** The live editor state, so a tab can be stored and restored intact. */
  get state(): EditorState {
    return this.view.state;
  }

  /**
   * Swaps in another document's state (spec feature 12).
   *
   * Each tab owns an `EditorState`, so undo history, selection and scroll
   * position all survive switching away and back — and, crucially, Ctrl+Z in
   * one tab can never undo into another tab's content.
   */
  swapState(state: EditorState): void {
    this.applyingExternalEdit = true;
    try {
      this.view.setState(state);
    } finally {
      this.applyingExternalEdit = false;
    }
  }

  setDiagnostics(diagnostics: Diagnostic[]): void {
    const doc = this.view.state.doc;
    const mapped: CmDiagnostic[] = [];

    for (const d of diagnostics) {
      if (d.severity === 'echo' || d.severity === 'info') continue;
      if (!d.span) continue;
      // Includes report spans in other files; their offsets mean nothing in this
      // document, so they appear in the console only.
      if (d.span.file !== 'main.scad' && d.span.file !== '<input>') continue;

      const from = Math.max(0, Math.min(d.span.start.offset, doc.length));
      const to = Math.max(from, Math.min(d.span.end.offset, doc.length));
      mapped.push({
        from,
        // A zero-width range renders no squiggle, so widen it by one character.
        to: to === from ? Math.min(from + 1, doc.length) : to,
        severity: d.severity === 'error' ? 'error' : 'warning',
        message: d.message,
        source: d.code,
      });
    }

    this.view.dispatch(setDiagnostics(this.view.state, mapped));
  }

  /** Moves the cursor to a 1-based line/column and scrolls it into view. */
  goTo(line: number, column = 1): void {
    const doc = this.view.state.doc;
    const target = doc.line(Math.max(1, Math.min(line, doc.lines)));
    const pos = Math.min(target.from + column - 1, target.to);
    this.view.dispatch({
      selection: { anchor: pos },
      effects: EditorView.scrollIntoView(pos, { y: 'center' }),
    });
    this.view.focus();
  }

  /** Replaces a source range, used by the Customizer to write values back. */
  replaceRange(from: number, to: number, text: string): void {
    this.view.dispatch({ changes: { from, to, insert: text } });
  }

  /**
   * Inserts text at the cursor, replacing any selection, and leaves the caret
   * after it. Used by the font picker's Insert action.
   */
  insertAtCursor(text: string): void {
    const range = this.view.state.selection.main;
    this.view.dispatch({
      changes: { from: range.from, to: range.to, insert: text },
      selection: { anchor: range.from + text.length },
      scrollIntoView: true,
    });
    this.view.focus();
  }

  undo(): void {
    undo(this.view);
  }

  redo(): void {
    redo(this.view);
  }

  focus(): void {
    this.view.focus();
  }

  setReadOnly(value: boolean): void {
    this.view.dispatch({ effects: this.readOnly.reconfigure(EditorState.readOnly.of(value)) });
  }

  destroy(): void {
    this.view.destroy();
  }
}
